<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?>
<h1>Shortlisting, decisions, and offers</h1><?php if (session('message')): ?><p class="notice"><?= esc(session('message')) ?></p><?php endif ?><?php if (session('errors')): ?><ul><?php foreach(session('errors') as $error): ?><li><?= esc($error) ?></li><?php endforeach ?></ul><?php endif ?>
<section class="admin-grid"><?php foreach($metrics as $label => $count): ?><article class="admin-card"><strong><?= esc((string) $count) ?></strong><br><?= esc(str_replace('_', ' ', $label)) ?></article><?php endforeach ?></section>
<h2>Create shortlist batch</h2><form method="post" action="<?= site_url('tenant/admissions/decisions/batches') ?>"><?= csrf_field() ?><label>Cycle ID <input name="admission_cycle_id" inputmode="numeric" required></label><label>Programme opening ID <input name="programme_opening_id" inputmode="numeric"></label><label>Batch code <input name="batch_code" required></label><label>Title <input name="title" required></label><label>Type <select name="batch_type"><option value="shortlist">Shortlist</option><option value="waitlist">Waitlist</option><option value="rejection">Rejection</option></select></label><label>Private notes <textarea name="private_notes"></textarea></label><button>Create batch</button></form>
<h2>Batches</h2><ul><?php foreach($batches as $batch): ?><li><?= esc($batch['batch_code']) ?> — <?= esc($batch['title']) ?> (<?= esc($batch['batch_type']) ?>)</li><?php endforeach ?></ul>
<h2>Current decisions</h2><table><thead><tr><th>Application</th><th>Decision</th><th>Status</th><th>Approval</th></tr></thead><tbody><?php foreach($decisions as $decision): ?><tr><td><?= esc($decision['applicant_application_id']) ?></td><td><?= esc($decision['decision_type']) ?></td><td><?= esc($decision['decision_status']) ?></td><td><?php if($decision['decision_status']==='pending_approval'): ?><form method="post" action="<?= site_url('tenant/admissions/decisions/'.$decision['id'].'/approve') ?>"><?= csrf_field() ?><button>Approve offer</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table>
<h2>Offers</h2><ul><?php foreach($offers as $offer): ?><li><?= esc($offer['offer_reference']) ?> — application <?= esc($offer['applicant_application_id']) ?> — <?= esc($offer['offer_status']) ?> expires <?= esc($offer['expires_at']) ?></li><?php endforeach ?></ul>
<?= $this->endSection() ?>
